function q(id, prompt, answer, accepted = [], decoys = [], _legacyTag = null, factKey = null, image = null, imageAlt = "") {
  return {
    id,
    prompt,
    answer,
    accepted: Array.from(new Set([answer, ...accepted].filter(Boolean))),
    decoys: Array.from(new Set(decoys.filter(Boolean))),
    factKey: factKey || id,
    image: image || null,
    imageAlt: image ? (imageAlt || "صورة السؤال") : "",
  };
}

