function uniquePermutations(items, length) {
  const result = [];
  const used = Array(items.length).fill(false);
  const current = [];
  function walk() {
    if (current.length === length) {
      result.push([...current]);
      return;
    }
    for (let i = 0; i < items.length; i += 1) {
      if (used[i]) continue;
      used[i] = true;
      current.push(items[i]);
      walk();
      current.pop();
      used[i] = false;
    }
  }
  walk();
  return result;
}

function buildSingleQuestionChallenges(categoryId, seeds) {
  // Use the curated harder seeds only. Every entry is exactly one prompt
  // with one expected answer; no multi-part "answer in order" challenges.
  const hardSeeds = seeds.slice(-5);
  return hardSeeds.map((item, index) => q(
    `${categoryId}-single-${String(index + 1).padStart(3, "0")}`,
    item.prompt,
    item.answer,
    item.accepted || [],
    item.decoys || [],
    null,
    `${categoryId}:single:${item.factKey || item.id}`,
  ));
}

function numericDecoys(value, delta = 1) {
  const n = Number(value);
  const candidates = [n - delta, n + delta, n - 2 * delta, n + 2 * delta, n + 10];
  return [...new Set(candidates.filter(Number.isFinite).map(String))].filter((item) => item !== String(value));
}

function gcd(a, b) {
  let x = Math.abs(a);
  let y = Math.abs(b);
  while (y) [x, y] = [y, x % y];
  return x;
}

function lcm(a, b) {
  return Math.abs(a * b) / gcd(a, b);
}

function buildHardMathQuestions() {
  const list = [];
  let id = 1;

  outerExpression:
  for (let a = 23; a <= 83; a += 3) {
    for (let b = 7; b <= 19; b += 2) {
      for (let c = 5; c <= 13; c += 2) {
        const d = ((a + b + c) % 17) + 9;
        const answer = a * b - c * c + d;
        list.push(q(
          `numbers-expression-${id++}`,
          `احسب من دون آلة حاسبة: (${a} × ${b}) − ${c}² + ${d} = ؟`,
          String(answer),
          [],
          numericDecoys(answer, Math.max(2, c - 2)),
          null,
          `numbers:expression:${a}:${b}:${c}:${d}`,
        ));
        if (list.length >= 900) break outerExpression;
      }
    }
  }

  let pairId = 1;
  outerGcd:
  for (let a = 54; a <= 186; a += 6) {
    for (let b = 35; b <= 155; b += 5) {
      if (gcd(a, b) <= 1) continue;
      const g = gcd(a, b);
      const l = lcm(a, b);
      list.push(q(
        `numbers-gcd-${pairId}`,
        `ما القاسم المشترك الأكبر للعددين ${a} و${b}؟`,
        String(g), [], numericDecoys(g, 1), null,
        `numbers:gcd:${a}:${b}`,
      ));
      list.push(q(
        `numbers-lcm-${pairId}`,
        `ما المضاعف المشترك الأصغر للعددين ${a} و${b}؟`,
        String(l), [], numericDecoys(l, Math.max(2, g)), null,
        `numbers:lcm:${a}:${b}`,
      ));
      pairId += 1;
      if (list.length >= 1450) break outerGcd;
    }
  }

  let modId = 1;
  outerMod:
  for (let a = 17; a <= 59; a += 2) {
    for (let exponent = 3; exponent <= 8; exponent += 1) {
      for (let mod = 7; mod <= 19; mod += 2) {
        const answer = Number(BigInt(a) ** BigInt(exponent) % BigInt(mod));
        list.push(q(
          `numbers-mod-${modId++}`,
          `ما باقي قسمة ${a}^${exponent} على ${mod}؟`,
          String(answer), [], [...new Set([0, 1, (answer + 1) % mod, (answer + 2) % mod, (answer + mod - 1) % mod].map(String))].filter((x) => x !== String(answer)), null,
          `numbers:mod:${a}:${exponent}:${mod}`,
        ));
        if (list.length >= 1900) break outerMod;
      }
    }
  }
  return list;
}


function flagEmojiToCode(flag) {
  return [...String(flag || "")]
    .filter((char) => {
      const codePoint = char.codePointAt(0);
      return codePoint >= 0x1F1E6 && codePoint <= 0x1F1FF;
    })
    .map((char) => String.fromCharCode(char.codePointAt(0) - 0x1F1E6 + 65))
    .join("")
    .toLowerCase();
}

function flagAssetPathFromEmoji(flag) {
  const code = flagEmojiToCode(flag);
  return code ? `assets/Countries/${code}.svg` : null;
}

function flagAssetPathFromCode(code) {
  return code ? `assets/Countries/${String(code).toLowerCase()}.svg` : null;
}

function buildModerateMathQuestions(targetCount = 1899) {
  const list = [];
  let id = 1;
  const push = (prompt, answer, decoys, key) => {
    if (list.length >= targetCount) return;
    list.push(q(
      `numbers-medium-${String(id++).padStart(4, "0")}`,
      prompt,
      String(answer),
      [],
      (decoys || []).map(String),
      null,
      `numbers:medium:${key}`,
    ));
  };

  // جمع وطرح متوسطان: أرقام مختلفة فعليًا وليست إعادة صياغة للسؤال نفسه.
  for (let a = 38; a <= 248 && list.length < targetCount; a += 7) {
    for (let b = 17; b <= 113 && list.length < targetCount; b += 6) {
      const c = ((a + b) % 29) + 8;
      const answer = a + b - c;
      push(`احسب: ${a} + ${b} − ${c} = ؟`, answer, numericDecoys(answer, 2), `sum:${a}:${b}:${c}`);
    }
  }

  // ضرب وقسمة بنتيجة صحيحة، بمستوى أخف من مسائل الباقي والقاسم المشترك في البنك الأصعب.
  for (let b = 4; b <= 18 && list.length < targetCount; b += 1) {
    for (let qv = 6; qv <= 46 && list.length < targetCount; qv += 2) {
      const a = b * qv;
      push(`إذا كان ${a} ÷ ${b} = ؟`, qv, numericDecoys(qv, 1), `division:${a}:${b}`);
    }
  }

  // نسب مئوية شائعة ولكن بأرقام متنوعة.
  const percentages = [10, 15, 20, 25, 30, 40, 50, 60, 75];
  for (let base = 40; base <= 520 && list.length < targetCount; base += 20) {
    for (const pct of percentages) {
      const answer = (base * pct) / 100;
      if (!Number.isInteger(answer)) continue;
      push(`كم يساوي ${pct}% من ${base}؟`, answer, numericDecoys(answer, Math.max(1, Math.round(answer * 0.08))), `percent:${pct}:${base}`);
      if (list.length >= targetCount) break;
    }
  }

  // متوسط حسابي لثلاثة أعداد متقاربة.
  for (let center = 18; center <= 318 && list.length < targetCount; center += 3) {
    for (let d = 2; d <= 10 && list.length < targetCount; d += 2) {
      const values = [center - d, center, center + d];
      push(`ما المتوسط الحسابي للأعداد ${values[0]}، ${values[1]}، ${values[2]}؟`, center, numericDecoys(center, 2), `average:${values.join(':')}`);
    }
  }

  // قوى وجذور مألوفة.
  for (let n = 6; n <= 45 && list.length < targetCount; n += 1) {
    const square = n * n;
    push(`ما مربع العدد ${n}؟`, square, numericDecoys(square, Math.max(2, n)), `square:${n}`);
    if (list.length >= targetCount) break;
    push(`ما الجذر التربيعي للعدد ${square}؟`, n, numericDecoys(n, 1), `sqrt:${square}`);
  }

  // أكمل العدد المطلوب بدقة حتى يساوي عدد الأسئلة المضافة العدد المستهدف.
  let serial = 1;
  while (list.length < targetCount) {
    const a = 120 + (serial % 181);
    const b = 15 + ((serial * 7) % 61);
    const c = 5 + ((serial * 11) % 31);
    const answer = a - b + c;
    push(`احسب: ${a} − ${b} + ${c} = ؟`, answer, numericDecoys(answer, 2), `final:${serial}:${a}:${b}:${c}`);
    serial += 1;
  }

  return list.slice(0, targetCount);
}

function buildModerateCountryQuestions() {
  const list = [];
  const allNames = [...new Set([
    ...COUNTRY_FLAG_DATA.map((entry) => entry[1]),
    ...MODERATE_COUNTRY_DATA.map((entry) => entry[1]),
  ])];
  const allCapitals = [...new Set([
    ...COUNTRY_FLAG_DATA.map((entry) => entry[2]).filter(Boolean),
    ...MODERATE_COUNTRY_DATA.map((entry) => entry[2]).filter(Boolean),
  ])];

  MODERATE_COUNTRY_DATA.forEach(([code, country, capital], index) => {
    const countryDecoys = [5, 13, 27, 41]
      .map((step) => allNames[(allNames.indexOf(country) + step) % allNames.length])
      .filter((item) => item && item !== country);
    const capitalDecoys = [3, 11, 19, 31]
      .map((step) => allCapitals[(allCapitals.indexOf(capital) + step) % allCapitals.length])
      .filter((item) => item && item !== capital);

    list.push(q(
      `countries-medium-flag-${index + 1}`,
      "خمن اسم الدولة من خلال صورة العلم:",
      country,
      [],
      countryDecoys,
      null,
      `countries:medium:flag:${code}`,
      flagAssetPathFromCode(code),
      `علم ${country}`,
    ));

    list.push(q(
      `countries-medium-capital-${index + 1}`,
      `ما هي عاصمة ${country}؟`,
      capital,
      [],
      capitalDecoys,
      null,
      `countries:medium:capital:${code}`,
    ));
  });

  return list;
}

function buildModeratePlayerQuestions(targetCount = 445) {
  const names = PLAYER_CAREERS.map((entry) => entry[0]);
  const list = [];
  PLAYER_CAREERS.forEach(([name, clubs], index) => {
    const uniqueClubs = clubs.filter((club, i) => clubs.indexOf(club) === i);
    const meta = PLAYER_META[name] || {};
    const decoys = playerDecoys(name, names, index, meta);

    // سؤال واحد وإجابة واحدة، لكن بقرائن أسهل نسبيًا: ناديان فقط من المسيرة.
    combinations(uniqueClubs, 2, Infinity).forEach((clubSet, clueIndex) => {
      if (list.length >= targetCount) return;
      list.push(q(
        `player-medium-${index}-clubs-${clueIndex}`,
        `خمن اللاعب الذي لعب خلال مسيرته لكل من ${clubSet[0]} و${clubSet[1]}.`,
        name,
        [],
        decoys,
        null,
        `player:medium:${name}:clubs:${clubSet.join('>')}`,
      ));
    });
  });

  // إذا لم تكف أزواج الأندية، نضيف ملفات تعريف حقيقية مختلفة في نوع المعلومة.
  PLAYER_CAREERS.forEach(([name, clubs], index) => {
    if (list.length >= targetCount) return;
    const uniqueClubs = clubs.filter((club, i) => clubs.indexOf(club) === i);
    const meta = PLAYER_META[name] || {};
    const decoys = playerDecoys(name, names, index, meta);
    if (meta.nationality && uniqueClubs.length) {
      list.push(q(
        `player-medium-${index}-nationality`,
        `خمن اللاعب: لاعب ${meta.nationality} ومن الأندية التي لعب لها ${uniqueClubs[0]}.`,
        name, [], decoys, null,
        `player:medium:${name}:nationality-club`,
      ));
    }
  });

  return list.slice(0, targetCount);
}

function buildHardCountryQuestions() {
  const list = [];
  const countryNames = COUNTRY_FLAG_DATA.map((entry) => entry[1]);
  const capitals = COUNTRY_FLAG_DATA.map((entry) => entry[2]).filter(Boolean);

  COUNTRY_FLAG_DATA.forEach(([flag, country, capital, nearby], index) => {
    const countryDecoys = [...new Set([
      ...(nearby || []),
      countryNames[(index + 5) % countryNames.length],
      countryNames[(index + 11) % countryNames.length],
    ])].filter((item) => item && item !== country).slice(0, 6);

    list.push(q(
      `countries-flag-country-${index + 1}`,
      "خمن اسم الدولة أو الإقليم من خلال صورة العلم:",
      country,
      [],
      countryDecoys,
      null,
      `countries:flag-country:${country}`,
      flagAssetPathFromEmoji(flag),
      `علم ${country}`,
    ));

    if (capital) {
      const capitalDecoys = [...new Set([
        capitals[(index + 3) % capitals.length],
        capitals[(index + 9) % capitals.length],
        capitals[(index + 17) % capitals.length],
        capitals[(index + 23) % capitals.length],
      ])].filter((item) => item && item !== capital).slice(0, 6);

      list.push(q(
        `countries-capital-${index + 1}`,
        `ما هي عاصمة ${country}؟`,
        capital,
        [],
        capitalDecoys,
        null,
        `countries:capital:${country}`,
      ));
    }
  });

  return list;
}

function combinations(items, length, limitCount = Infinity) {
  const result = [];
  function walk(start, current) {
    if (result.length >= limitCount) return;
    if (current.length === length) {
      result.push([...current]);
      return;
    }
    for (let i = start; i < items.length; i += 1) {
      current.push(items[i]);
      walk(i + 1, current);
      current.pop();
      if (result.length >= limitCount) return;
    }
  }
  walk(0, []);
  return result;
}

function playerDecoys(name, names, index, meta) {
  const sameNation = meta?.nationality
    ? names.filter((candidate) => candidate !== name && PLAYER_META[candidate]?.nationality === meta.nationality)
    : [];
  const nearby = [1, 5, 11, 17, 23].map((step) => names[(index + step) % names.length]).filter((candidate) => candidate !== name);
  return [...new Set([...sameNation, ...nearby])].slice(0, 6);
}

function buildPlayerGuessQuestions() {
  const names = PLAYER_CAREERS.map((entry) => entry[0]);
  const list = [];
  PLAYER_CAREERS.forEach(([name, clubs], index) => {
    const uniqueClubs = clubs.filter((club, i) => clubs.indexOf(club) === i);
    const meta = PLAYER_META[name] || {};
    const decoys = playerDecoys(name, names, index, meta);

    combinations(uniqueClubs, Math.min(3, uniqueClubs.length), 10).forEach((clubSet, clueIndex) => {
      if (clubSet.length < 2) return;
      list.push(q(
        `player-${index}-clubs-${clueIndex}`,
        `خمن اللاعب الذي جمعت مسيرته بين هذه المحطات: ${clubSet.join("، ")}.`,
        name, [], decoys, null,
        `player:${name}:clubs:${clubSet.join(">")}`,
      ));
    });

    if (uniqueClubs.length >= 2) {
      list.push(q(
        `player-${index}-start-end`,
        `خمن اللاعب: بدأ ضمن مسيرته مع ${uniqueClubs[0]}، وظهر لاحقًا بقميص ${uniqueClubs[uniqueClubs.length - 1]}، ولعب لعدد من الأندية بينها ${uniqueClubs[Math.floor(uniqueClubs.length / 2)]}.`,
        name, [], decoys, null,
        `player:${name}:start-middle-end`,
      ));
    }

    (meta.aliases || []).forEach((alias, aliasIndex) => {
      const clubClue = uniqueClubs[Math.min(aliasIndex + 1, uniqueClubs.length - 1)] || uniqueClubs[0] || "نادٍ أوروبي";
      list.push(q(
        `player-${index}-alias-${aliasIndex}`,
        `من اللاعب المعروف بلقب «${alias}»، والذي لعب أيضًا مع ${clubClue}؟`,
        name, [], decoys, null,
        `player:${name}:alias:${alias}`,
      ));
    });

    (meta.achievements || []).forEach((achievement, achievementIndex) => {
      const extra = meta.nationality ? ` وهو لاعب ${meta.nationality}` : "";
      const careerHint = uniqueClubs.length >= 2
        ? ` ومن محطات مسيرته ${uniqueClubs[0]} و${uniqueClubs[uniqueClubs.length - 1]}`
        : uniqueClubs.length === 1
          ? ` وارتبطت مسيرته بنادي ${uniqueClubs[0]}`
          : "";
      list.push(q(
        `player-${index}-achievement-${achievementIndex}`,
        `خمن اللاعب من هذه المعلومة: ${achievement}${extra}${careerHint}.`,
        name, [], decoys, null,
        `player:${name}:achievement:${achievementIndex}`,
      ));
    });

    if (meta.position && meta.nationality && uniqueClubs.length) {
      list.push(q(
        `player-${index}-profile`,
        `خمن اللاعب: ${meta.nationality}، مركزه ${meta.position}، ومن محطات مسيرته ${uniqueClubs.slice(0, Math.min(3, uniqueClubs.length)).join(" ثم ")}.`,
        name, [], decoys, null,
        `player:${name}:profile`,
      ));
    }
  });
  return list;
}


