function babEventPromptKind(prompt) {
  const text = String(prompt || "").trim();
  if (/^(من|لمن|ممن)(\s|$)/.test(text)) return "person";
  if (/^أين(\s|$)/.test(text)) return "place";
  if (/^كم(\s|$)/.test(text)) return "number";
  if (/^هل(\s|$)/.test(text)) return "binary";
  return "event";
}

function buildBabEventDecoys(prompt, answer, index, entries) {
  const kind = babEventPromptKind(prompt);
  const pool = [...new Set(entries
    .filter((entry) => entry.answer !== answer && entry.kind === kind)
    .map((entry) => entry.answer))];
  if (!pool.length) return [];
  const out = [];
  for (let step = 0; step < pool.length && out.length < 5; step += 1) {
    const candidate = pool[(index + step * 3) % pool.length];
    if (candidate && candidate !== answer && !out.includes(candidate)) out.push(candidate);
  }
  return out;
}

function buildBabAlHaraEventQuestions() {
  const result = [];
  const entries = BAB_AL_HARA_EVENT_PAIRS.flatMap(([, prompt1, answer1, prompt2, answer2]) => [
    { prompt: prompt1, answer: answer1, kind: babEventPromptKind(prompt1) },
    { prompt: prompt2, answer: answer2, kind: babEventPromptKind(prompt2) },
  ]);

  BAB_AL_HARA_EVENT_PAIRS.forEach(([id, prompt1, answer1, prompt2, answer2], index) => {
    result.push(q(
      `bab-event-${id}-a`,
      prompt1,
      answer1,
      [],
      buildBabEventDecoys(prompt1, answer1, index * 2, entries),
      null,
      `bab-al-hara:event:${id}:a`,
    ));
    result.push(q(
      `bab-event-${id}-b`,
      prompt2,
      answer2,
      [],
      buildBabEventDecoys(prompt2, answer2, index * 2 + 1, entries),
      null,
      `bab-al-hara:event:${id}:b`,
    ));
  });
  return result;
}


