function buildEasyMathExpansion(targetCount = 3799) {
  const list = [];
  let id = 1;

  // مسائل جمع وطرح وضرب وقسمة مباشرة، كل مسألة بأرقام مختلفة فعليًا.
  outerAdd:
  for (let a = 20; a <= 219; a += 1) {
    for (let b = 5; b <= 24; b += 1) {
      const answer = a + b;
      list.push(q(
        `numbers-easy2-${String(id++).padStart(4, "0")}`,
        `احسب: ${a} + ${b} = ؟`,
        String(answer), [], numericDecoys(answer, 2), null,
        `numbers:easy2:add:${a}:${b}`,
      ));
      if (list.length >= targetCount) break outerAdd;
    }
  }

  let serial = 1;
  while (list.length < targetCount) {
    const a = 50 + serial;
    const b = 3 + (serial % 17);
    const answer = a - b;
    list.push(q(
      `numbers-easy2-${String(id++).padStart(4, "0")}`,
      `احسب: ${a} − ${b} = ؟`,
      String(answer), [], numericDecoys(answer, 2), null,
      `numbers:easy2:sub:${a}:${b}`,
    ));
    serial += 1;
  }

  return list.slice(0, targetCount);
}

function buildCountryEasyVariants(existingQuestions, targetCount) {
  return existingQuestions.slice(0, targetCount).map((item, index) => {
    if (item.image) {
      return q(
        `countries-easy2-flag-${index + 1}`,
        "ما اسم الدولة أو الإقليم الذي يمثله هذا العلم؟",
        item.answer,
        item.accepted || [],
        item.decoys || [],
        null,
        `countries:easy2:flag:${item.factKey || item.id}`,
        item.image,
        item.imageAlt || `علم ${item.answer}`,
      );
    }

    const match = String(item.prompt || "").match(/عاصمة\s+(.+?)[؟?]?$/);
    const country = match?.[1]?.replace(/[؟?]+$/, "").trim();
    const prompt = country
      ? `اذكر عاصمة ${country}.`
      : `ما العاصمة المقصودة في هذا السؤال: ${item.prompt}`;
    return q(
      `countries-easy2-capital-${index + 1}`,
      prompt,
      item.answer,
      item.accepted || [],
      item.decoys || [],
      null,
      `countries:easy2:capital:${item.factKey || item.id}`,
    );
  });
}

function buildPlayerEasyExpansion(targetCount = 890) {
  const names = PLAYER_CAREERS.map(([name]) => name);
  const list = [];
  const seen = new Set();
  let id = 1;

  const push = (prompt, name, decoys, key) => {
    if (list.length >= targetCount || seen.has(prompt)) return;
    seen.add(prompt);
    list.push(q(
      `player-easy2-${String(id++).padStart(4, "0")}`,
      prompt,
      name,
      [],
      decoys,
      null,
      `player:easy2:${key}`,
    ));
  };

  PLAYER_CAREERS.forEach(([name, clubs], index) => {
    const meta = PLAYER_META[name] || {};
    const uniqueClubs = [...new Set(clubs)];
    const decoys = playerDecoys(name, names, index, meta);

    uniqueClubs.forEach((club, clubIndex) => {
      if (meta.nationality && meta.position) {
        push(`خمن اللاعب: ${meta.nationality}، مركزه ${meta.position}، ولعب مع ${club}.`, name, decoys, `${name}:club-profile:${clubIndex}`);
      } else if (meta.nationality) {
        push(`خمن اللاعب: لاعب ${meta.nationality} ومن الأندية التي لعب لها ${club}.`, name, decoys, `${name}:club-nation:${clubIndex}`);
      }
    });

    combinations(uniqueClubs, 2, Infinity).forEach((pair, pairIndex) => {
      const nation = meta.nationality ? ` وهو ${meta.nationality}` : "";
      push(`خمن اللاعب الذي لعب مع ${pair[0]} و${pair[1]}${nation}.`, name, decoys, `${name}:pair:${pairIndex}`);
      if (meta.position) {
        push(`من اللاعب الذي مركزه ${meta.position} وارتدى قميصي ${pair[0]} و${pair[1]}؟`, name, decoys, `${name}:pair-position:${pairIndex}`);
      }
    });

    (meta.achievements || []).forEach((achievement, achievementIndex) => {
      push(`خمن اللاعب من الإنجاز التالي: ${achievement}.`, name, decoys, `${name}:achievement:${achievementIndex}`);
      if (meta.nationality) {
        push(`خمن اللاعب ${meta.nationality} المرتبط بهذا الإنجاز: ${achievement}.`, name, decoys, `${name}:achievement-nation:${achievementIndex}`);
      }
    });

    (meta.aliases || []).forEach((alias, aliasIndex) => {
      push(`من اللاعب المعروف بلقب «${alias}»؟`, name, decoys, `${name}:alias:${aliasIndex}`);
      if (meta.nationality) push(`خمن اللاعب ${meta.nationality} المعروف بلقب «${alias}».`, name, decoys, `${name}:alias-nation:${aliasIndex}`);
    });
  });

  // قرائن من ثلاث محطات مع الجنسية/المركز، وهي أسهل من أسئلة المسيرة المجردة لأنها تعطي معلومة إضافية.
  PLAYER_CAREERS.forEach(([name, clubs], index) => {
    if (list.length >= targetCount) return;
    const meta = PLAYER_META[name] || {};
    const uniqueClubs = [...new Set(clubs)];
    const decoys = playerDecoys(name, names, index, meta);
    combinations(uniqueClubs, Math.min(3, uniqueClubs.length), Infinity).forEach((set, clueIndex) => {
      if (list.length >= targetCount || set.length < 2) return;
      const extra = [meta.nationality, meta.position].filter(Boolean).join("، ");
      push(`خمن اللاعب: ${extra ? `${extra}، ` : ""}ومن أندية مسيرته ${set.join(" و")}.`, name, decoys, `${name}:triple:${clueIndex}`);
    });
  });

  return list.slice(0, targetCount);
}

function buildBabAlHaraEasyExpansion(existingQuestions, targetCount = 90) {
  return existingQuestions.slice(0, targetCount).map((item, index) => {
    let prompt = String(item.prompt || "");
    if (item.id.startsWith("bab-cast-actor-")) {
      prompt = prompt.replace("من الممثل الذي جسّد شخصية", "أي ممثل أدّى شخصية");
    } else if (item.id.startsWith("bab-cast-role-")) {
      prompt = prompt.replace("ما الشخصية التي جسّدها الممثل", "أي شخصية من باب الحارة أدّاها الممثل");
    } else {
      prompt = `سؤال مباشر من باب الحارة: ${prompt}`;
    }
    return q(
      `bab-easy2-${String(index + 1).padStart(3, "0")}`,
      prompt,
      item.answer,
      item.accepted || [],
      item.decoys || [],
      null,
      `bab-al-hara:easy2:${item.factKey || item.id}`,
    );
  });
}


function enrichDecoys(bank) {
  Object.entries(bank).forEach(([categoryId, questions]) => {
    const answers = [...new Set(questions.map((item) => item.answer).filter(Boolean))];
    questions.forEach((question, index) => {
      if (question.decoys?.length >= 3) return;
      const nearby = [];
      for (let step = 1; step < answers.length && nearby.length < 6; step += 1) {
        const candidate = answers[(index + step) % answers.length];
        if (candidate && candidate !== question.answer && !nearby.includes(candidate)) nearby.push(candidate);
      }
      question.decoys = [...new Set([...(question.decoys || []), ...nearby])].slice(0, 8);
    });
  });
}

const SPECIAL_CATEGORIES = new Set(["numbers", "countries", "player_guess"]);
const QUESTION_BANK = {};

// الفئات العامة: البنك السابق (10) + عشرة أسئلة جديدة أخف/متوسطة = 20 سؤالًا لكل فئة.
Object.keys(BASE_BANK).forEach((categoryId) => {
  if (SPECIAL_CATEGORIES.has(categoryId)) return;
  const harderSeeds = CHALLENGE_SEED_BANK[categoryId] || [];
  const moderateSeeds = BASE_BANK[categoryId] || [];
  QUESTION_BANK[categoryId] = [
    ...buildSingleQuestionChallenges(categoryId, harderSeeds),
    ...moderateSeeds,
    ...(EXTRA_EASY_MEDIUM_BANK[categoryId] || []),
  ];
});

// باب الحارة: 120 سؤالًا عن أحداث المسلسل + 60 سؤالًا مختارًا عن الشخصيات والمعلومات العامة.
// بذلك تصبح غالبية الفئة (ثلثاها تقريبًا) عن الأحداث الدرامية نفسها.
const babOriginal = buildBabAlHaraQuestions();
const babEventQuestions = buildBabAlHaraEventQuestions();
QUESTION_BANK.bab_al_hara = [
  ...babEventQuestions,
  ...babOriginal.slice(0, 60),
];

// بلاد الرافدين: 60 سؤالًا سابقًا + 60 سؤالًا جديدًا أسهل/متوسطًا.
QUESTION_BANK.iraq = [
  ...(QUESTION_BANK.iraq || []),
  ...MESOPOTAMIA_EXTRA_QUESTIONS,
  ...MESOPOTAMIA_EASY_MEDIUM_EXTRA,
];

// الأرقام والحساب: مضاعفة 3799 إلى 7598 بمسائل جديدة فعلية أخف/متوسطة.
const numbersOriginal = [
  ...buildHardMathQuestions(),
  ...buildModerateMathQuestions(1899),
];
QUESTION_BANK.numbers = [
  ...numbersOriginal,
  ...buildEasyMathExpansion(numbersOriginal.length),
];

// الدول والعواصم: نحافظ على طريقتي السؤال فقط (صورة علم -> دولة، دولة -> عاصمة)،
// ونضيف نسخة أسهل مساوية لعدد الأسئلة السابقة مع نفس الحقائق الجغرافية الموثوقة.
const countriesOriginal = [
  ...buildHardCountryQuestions(),
  ...buildModerateCountryQuestions(),
];
QUESTION_BANK.countries = [
  ...countriesOriginal,
  ...buildCountryEasyVariants(countriesOriginal, countriesOriginal.length),
];

// خمن اللاعب: مضاعفة العدد بقرائن أبسط تجمع الجنسية/المركز/الأندية/اللقب/الإنجاز.
const playerOriginal = [
  ...buildPlayerGuessQuestions(),
  ...buildModeratePlayerQuestions(445),
];
QUESTION_BANK.player_guess = [
  ...playerOriginal,
  ...buildPlayerEasyExpansion(playerOriginal.length),
];

enrichDecoys(QUESTION_BANK);

export { QUESTION_BANK };
export function categoryHasQuestions(categoryId) {
  return Array.isArray(QUESTION_BANK[categoryId]) && QUESTION_BANK[categoryId].length > 0;
}
export function getQuestionCount(categoryId) {
  return Array.isArray(QUESTION_BANK[categoryId]) ? QUESTION_BANK[categoryId].length : 0;
}
export function getTotalQuestionCount() {
  return Object.values(QUESTION_BANK).reduce((sum, items) => sum + items.length, 0);
}
export function getUniqueFactCount() {
  return new Set(Object.values(QUESTION_BANK).flat().map((item) => item.factKey)).size;
}
